if (Test-Path ".\orbyteflow\src") { Get-ChildItem -Path ".\orbyteflow\src" -Recurse -File | Where-Object { $_.Extension -match '^\.(ts|tsx|css)$' -and $_.FullName -notmatch '[\\/](node_modules|\.next|dist|build|\.cache|coverage|out)[\\/]' } | ForEach-Object { "`n========== FILE: $($_.FullName) ==========`n"; Get-Content -LiteralPath $_.FullName -Raw } | Set-Content -LiteralPath ".\frontend_code.txt" -Encoding UTF8 }